def mean_absolute_deviation(numbers: List[float]) -> float:
    """ Calculate Mean Absolute Deviation around the mean. """
    if not numbers:
        raise ValueError("Input list cannot be empty.")
    if not all(isinstance(n, (int, float)) for n in numbers):
