import math
def truncate_number(number: float) -> float:
    """Given a positive floating point number, return the decimal part."""
    if not isinstance(number, (int, float)):
        raise TypeError("Input must be a number.")
    if number < 0:
        raise ValueError("Input must be a positive number.")

    # math.modf is efficient and handles precision well
    return math.modf(float(number))[0]

from typing import List
def separate_paren_groups(paren_string: str) -> List[str]:
    """Separate groups of nested parentheses."""
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string.")

    result = []
    current_group = []
    nesting_level = 0

    # Iterate directly to avoid creating an intermediate string
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            nesting_level += 1
            current_group.append(char)
        elif char == ')':
            nesting_level -= 1
            if nesting_level < 0:
                raise ValueError("Unbalanced parentheses: found closing brace before opening.")
            current_group.append(char)
            if nesting_level == 0:
                result.append("".join(current_group))
                current_group = []
        else:
            # Ignore other characters as per requirements
            continue

    if nesting_level != 0:
        raise ValueError("Unbalanced parentheses: input string is not balanced.")

    return result

from typing import List
def below_zero(operations: List[int]) -> bool:
    """Detect if the balance falls below zero."""
    if not isinstance(operations, list) or not all(isinstance(op, int) for op in operations):
        raise TypeError("Input must be a list of integers.")

    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

from typing import List
def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Check if any two numbers are closer than the threshold."""
    if not isinstance(threshold, (int, float)) or threshold < 0:
        raise ValueError("Threshold must be a non-negative number.")

    if not isinstance(numbers, list) or not all(isinstance(n, (int, float)) for n in numbers):
        raise TypeError("Input must be a list of numbers.")

    if len(numbers) < 2:
        return False

    # O(n log n) time complexity, O(n) space complexity
    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if sorted_nums[i+1] - sorted_nums[i] < threshold:
            return True
    return False

from typing import List
def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    """
    if not isinstance(paren_string, str):
        raise TypeError("Input must be a string.")

    # Security check: ensure only valid characters are present
    if any(char not in '() ' for char in paren_string):
        raise ValueError("Input string contains invalid characters.")

    def get_max_depth(group: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
                if current_depth < 0:
                    raise ValueError("Invalid parenthesis structure: unbalanced closing parenthesis.")
        if current_depth != 0:
            raise ValueError("Invalid parenthesis structure: unbalanced opening parenthesis.")
        return max_depth

    return [get_max_depth(group) for group in paren_string.split()]

from typing import List
def intersperse(numbers: List[int], delimeter: int) -> List[int]:
    """ Insert a number 'delimeter' between every two consecutive elements of input list `numbers' """
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list.")
    if not all(isinstance(n, int) for n in numbers):
        raise TypeError("All elements must be integers.")
    if not isinstance(delimeter, int):
        raise TypeError("Delimeter must be an integer.")

    if not numbers:
        return []

    # Pre-allocate list to avoid dynamic resizing overhead
    n = len(numbers)
    result = [0] * (2 * n - 1)

    for i, num in enumerate(numbers):
        result[2 * i] = num
        if i < n - 1:
            result[2 * i + 1] = delimeter

    return result

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Inputs must be strings.")
    if len(a) != len(b):
        raise ValueError("Strings must have the same length.")
    if not all(c in '01' for c in a) or not all(c in '01' for c in b):
        raise ValueError("Strings must consist only of '0's and '1's.")

    return "".join('1' if x != y else '0' for x, y in zip(a, b))

def string_sequence(n: int) -> str:
    """ Return a string containing space-delimited numbers starting from 0 upto n inclusive.
    >>> string_sequence(0)
    '0'
    >>> string_sequence(5)
    '0 1 2 3 4 5'
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    return " ".join(str(i) for i in range(n + 1))

def count_distinct_characters(string: str) -> int:
    """ Given a string, find out how many distinct characters (regardless of case) does it consist of
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
    """
    if not isinstance(string, str):
        raise TypeError("Input must be a string.")
    return len(set(string.lower()))

